"""Custom steps of destination `sas_restructure_destination` — generated by package-factory 0.9.0. Do not edit: change the requirement and run `pkf create`."""
from __future__ import annotations

import logging
import posixpath
import re


MAX_KEY_BYTES = 1024


SLASH_FORMATS = ("adam", "sdtm")


OTHERS_EXCLUDED = ("/med", "/cdap", "/idap", "/anon", "_anon_")


DEFAULT_EXCLUDED = ("/data_reuse/", "_anon_", "/cdar/")


DATA_FORMATS = ("adam", "sdtm", "raw")


MAX_TAG_VALUE_LENGTH = 256


TAG_VALUE_PATTERN = r"[\w\s+\-=.:/@]*"


TAG_KEY = "ADDITIONAL_TAG"


def folder_path(path: str) -> str:
    """Return the folder part of a package path with '/' at both ends.

    Args:
        path: Package path relative to incoming/.

    Returns:
        The wrapped folder path, or '/' when the file has no folder.
    """
    directory = posixpath.dirname(path)
    return "/" + directory + "/" if directory else "/"


def slash_format(folder: str) -> str | None:
    """Work out the slash data format of a wrapped folder path (R-DST-2).

    Args:
        folder: Wrapped folder path.

    Returns:
        'adam', 'sdtm', 'raw' or None.
    """
    for data_format in SLASH_FORMATS:
        if f"/{data_format}/" in folder:
            return data_format
    if "raw/" in folder:
        return "raw"
    return None


def underscore_format(folder: str) -> str | None:
    """Work out the underscore data format used by anonymised folders (R-DST-3).

    Args:
        folder: Wrapped folder path.

    Returns:
        'adam', 'sdtm', 'raw' or None.
    """
    if "_adam_" in folder:
        return "adam"
    if "_sdtm_" in folder:
        return "sdtm"
    if "_raw_" in folder or "_restricted_raw_" in folder:
        return "raw"
    return None


def matching_rules(folder: str) -> list[str]:
    """Check every rule against the wrapped folder path and return all matches in rule order.

    Args:
        folder: Wrapped folder path.

    Returns:
        Names of the matching rules.
    """
    has_slash_format = slash_format(folder) is not None
    reuse = "/data_reuse/" in folder and has_slash_format
    checks = [
        ("CDAP", reuse and "/cdap_" in folder),
        ("IDAP", reuse and "/idap" in folder),
        ("MED", reuse and "/med" in folder),
        ("ANON", "_anon_" in folder and underscore_format(folder) is not None),
        ("CDAR", "/cdar/" in folder and has_slash_format),
        ("OTHERS", reuse and not any(marker in folder for marker in OTHERS_EXCLUDED)),
        ("DEFAULT", not any(marker in folder for marker in DEFAULT_EXCLUDED)),
    ]
    return [name for name, matched in checks if matched]


def ia_label(text: str) -> str:
    """Turn an interim marker like ia300, ia1 or ia_psc into ia_300, ia_1, ia_psc.

    Args:
        text: The interim marker.

    Returns:
        The normalised interim label.
    """
    rest = text[2:] if text.lower().startswith("ia") else text
    rest = rest.lstrip("_")
    return "ia_" + rest


def target_cdap(study: str, folder: str, last: str, fmt: str, file: str) -> str:
    """Build the CDAP target (R-DST-8, R-DST-9, R-DST-10).

    Args:
        study: Study ID.
        folder: Wrapped folder path.
        last: Last folder.
        fmt: Slash data format.
        file: File name.

    Returns:
        The target key.

    Raises:
        ValueError: When the last folder has too few '_' parts.
    """
    if "/cdap_csr" in folder:
        return f"{study}/extended_primary_use/primary/{fmt}/{file}"
    parts = last.split("_")
    if "_ia" in last:
        if len(parts) < 3:
            raise ValueError("CDAP interim: last folder has fewer than 3 _ parts")
        return f"{study}/extended_primary_use/interim/{fmt}/{ia_label(parts[2])}/{file}"
    if len(parts) < 2:
        raise ValueError("CDAP other: last folder has fewer than 2 _ parts")
    return f"{study}/extended_primary_use/other/{fmt}/{parts[1]}/{file}"


def target_anon(study: str, folder: str, last: str, fmt: str, file: str) -> str:
    """Build the ANON target (R-DST-13, R-DST-14).

    Args:
        study: Study ID.
        folder: Wrapped folder path.
        last: Last folder.
        fmt: Underscore data format.
        file: File name.

    Returns:
        The target key.

    Raises:
        ValueError: When the last '_' part is empty.
    """
    if "_anon_csr" in folder:
        return f"{study}/anonymised/primary/{fmt}/{file}"
    part = last.rsplit("_", 1)[-1]
    if part == "":
        raise ValueError("ANON: empty last _ part")
    if part.startswith("ia"):
        return f"{study}/anonymised/interim/{fmt}/{ia_label(part)}/{file}"
    return f"{study}/anonymised/other/{fmt}/{part}/{file}"


def target_cdar(study: str, folder: str, fmt: str, file: str) -> str:
    """Build the CDAR target from the reporting level after 'ar' (R-DST-15 to R-DST-19).

    Args:
        study: Study ID.
        folder: Wrapped folder path.
        fmt: Slash data format.
        file: File name.

    Returns:
        The target key.

    Raises:
        ValueError: When there is no ar folder, no level, or the level is a data format.
    """
    segments = [segment for segment in folder.split("/") if segment]
    index = next((i for i, segment in enumerate(segments) if segment.lower() == "ar"), None)
    if index is None:
        raise ValueError("CDAR: no ar folder")
    if index + 1 >= len(segments):
        raise ValueError("CDAR: no reporting level after ar")
    level = segments[index + 1]
    low = level.lower()
    if low in DATA_FORMATS:
        raise ValueError(f"CDAR: reporting level {level} is a data format")
    if low == "csr":
        return f"{study}/primary/complete/{fmt}/{file}"
    if low.startswith("ia"):
        return f"{study}/primary/interim/{fmt}/{ia_label(level)}/{file}"
    return f"{study}/primary/other/{fmt}/{level}/{file}"


def decide_target(path: str) -> tuple[str, str, str]:
    """Return (key, rule, reason) for one package path (R-DST-1 to R-DST-23).

    Args:
        path: Package path relative to incoming/.

    Returns:
        The key, the matched rule (empty on failure) and the error reason (empty on success).

    Raises:
        ValueError: When even the error/ key is longer than 1024 bytes.
    """
    folder = folder_path(path)
    file = posixpath.basename(path)
    study = path.split("/", 1)[0]
    last = folder.strip("/").rsplit("/", 1)[-1]
    error_key = "error/" + path
    rules = matching_rules(folder)
    reason = ""
    if not rules:
        reason = "no rule matched"
    elif len(rules) > 1:
        reason = "several rules matched: " + ", ".join(rules)
    else:
        rule = rules[0]
        sf = slash_format(folder)
        uf = underscore_format(folder)
        builders = {
            "CDAP": lambda: target_cdap(study, folder, last, sf, file),
            "IDAP": lambda: f"{study}/internal_reuse/{sf}/{last}/{file}",
            "MED": lambda: f"{study}/external_reuse/{sf}/{last}/{file}",
            "ANON": lambda: target_anon(study, folder, last, uf, file),
            "CDAR": lambda: target_cdar(study, folder, sf, file),
            "OTHERS": lambda: f"{study}/other/{sf}/{last}/{file}",
            "DEFAULT": lambda: path,
        }
        try:
            key = builders[rule]()
        except ValueError as exc:
            reason = f"{rule}: {exc}"
        if not reason and len(key.encode("utf-8")) > MAX_KEY_BYTES:
            reason = f"{rule}: target key longer than 1024 bytes"
        if not reason:
            return key, rule, ""
    if len(error_key.encode("utf-8")) > MAX_KEY_BYTES:
        raise ValueError(f"error key longer than 1024 bytes: {path}")
    return error_key, "", reason


def restructure_keys(layout, params, ctx):
    """Set each unplaced file's key to its rule target or error/<path> (R-DST-1 to R-DST-23, R-RUN-2).

    Args:
        layout: The destination layout with files, keys and vars.
        params: Run variables.
        ctx: Run context.

    Returns:
        The layout with every file's key set.
    """
    logger = logging.getLogger(__name__)
    for path in layout["files"]:
        if layout["keys"].get(path):
            continue
        key, rule, reason = decide_target(path)
        layout["keys"][path] = key
        logger.info("source=incoming/%s target=%s rule=%s", path, key, rule or f"error reason={reason}")
    return layout


def tag_value_valid(value: str) -> bool:
    """Check that a tag value is at most 256 characters and uses only allowed S3 tag characters.

    Args:
        value: The tag value.

    Returns:
        True when S3 accepts the value.
    """
    if len(value) > MAX_TAG_VALUE_LENGTH:
        return False
    return re.fullmatch(TAG_VALUE_PATTERN, value, re.UNICODE) is not None


def move_and_tag(transfers, params, ctx, aws):  # noqa: C901
    """Move each file server-side, then replace its tags unless it went to error/.

    Implements R-AFT-1 to R-AFT-6, R-RUN-1 to R-RUN-3. The I/O stages are inner functions because the plan
    allows only the named pure helpers at module level; that is why the complexity rule is waived here.

    Args:
        transfers: One dict per file to deliver, with its computed target_key.
        params: Run variables.
        ctx: Run context with the delivery settings.
        aws: S3 clients and logger.

    Returns:
        One result dict per transfer.
    """
    logger = aws.log or logging.getLogger(__name__)
    delivery = ctx.get("delivery") or {}

    def decide(path):
        try:
            return decide_target(path)  # noqa: F821 - defined by restructure_keys in the same generated module
        except ValueError as exc:
            return "", "", str(exc)

    def copy_extra(transfer):
        pairs = [
            ("CopySourceIfMatch", transfer.get("etag")),
            ("ServerSideEncryption", delivery.get("server_side_encryption")),
            ("SSEKMSKeyId", delivery.get("kms_key_id")),
        ]
        return {name: value for name, value in pairs if value}

    def move(transfer):
        source = {"Bucket": transfer["source_bucket"], "Key": transfer["source_key"]}
        bucket, key = transfer["target_bucket"], transfer["target_key"]
        try:
            aws.s3_destination.copy(source, bucket, key, ExtraArgs=copy_extra(transfer), SourceClient=aws.s3_source)
        except Exception as exc:  # noqa: BLE001 - one file's failure must not stop the others (R-AFT-2)
            return False, f"copy failed: {exc}"
        try:
            head = aws.s3_destination.head_object(Bucket=bucket, Key=key)
            if head["ContentLength"] != transfer["size"]:
                raise ValueError(f"size {head['ContentLength']} != {transfer['size']}")
        except Exception as exc:  # noqa: BLE001 - recorded as a failed result (R-AFT-2)
            return False, f"target check failed: {exc}"
        try:
            response = aws.s3_source.delete_object(Bucket=source["Bucket"], Key=source["Key"])
        except Exception as exc:  # noqa: BLE001 - recorded as a failed result (R-RUN-3)
            return False, f"copied but source delete failed: {exc}"
        if response.get("DeleteMarker") or response.get("VersionId"):
            return True, f" delete marker {response.get('VersionId')}"
        return True, ""

    def tag(transfer):
        value = transfer["path"]
        if not tag_value_valid(value):
            logger.warning("tag value not allowed for %s", transfer["target_key"])
            return " tag skipped (warning)"
        try:
            aws.s3_destination.put_object_tagging(
                Bucket=transfer["target_bucket"],
                Key=transfer["target_key"],
                Tagging={"TagSet": [{"Key": TAG_KEY, "Value": value}]},
            )
        except Exception as exc:  # noqa: BLE001 - tagging failure is a warning only (R-AFT-5)
            logger.warning("tagging failed for %s: %s", transfer["target_key"], exc)
            return f" tagging failed (warning): {exc}"
        return ""

    results = []
    for transfer in transfers:
        _key, rule, reason = decide(transfer["path"])
        to_error = rule == ""
        label = f"rule {rule}" if rule else f"error: {reason}"
        moved, note = move(transfer)
        if not moved:
            status, detail = "failed", f"{note}; {label}"
        else:
            status = "moved_to_error" if to_error else "moved"
            detail = label + note + ("" if to_error else tag(transfer))
        logger.info(
            "source=s3://%s/%s target=%s status=%s %s",
            transfer["source_bucket"], transfer["source_key"], transfer["target_key"], status, detail,
        )
        results.append({"path": transfer["path"], "key": transfer["target_key"], "status": status, "detail": detail})
    return results
